import{_ as a,o as e,c as d,a3 as s}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"技术细节","description":"","frontmatter":{},"headers":[],"relativePath":"technical.md","filePath":"technical.md","lastUpdated":null}'),o={name:"technical.md"};function i(r,t,n,l,c,h){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="技术细节" tabindex="-1">技术细节 <a class="header-anchor" href="#技术细节" aria-label="Permalink to &quot;技术细节&quot;">​</a></h1><p>给想深入框架 / 改编译流程的人看。<strong>玩家和 Mod 作者不需要读这一页。</strong></p><h2 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h2><p>做法是：<strong>把游戏的 <code>Assembly-CSharp.dll</code> 反编译成 C# 源码，在里面加代码，再整个重新编译回去</strong>。</p><p>这决定了后面所有技术细节。</p><hr><h2 id="一、为什么验证基准必须是「它自己的补丁前状态」" tabindex="-1">一、为什么验证基准必须是「它自己的补丁前状态」 <a class="header-anchor" href="#一、为什么验证基准必须是「它自己的补丁前状态」" aria-label="Permalink to &quot;一、为什么验证基准必须是「它自己的补丁前状态」&quot;">​</a></h2><p>这是开发中踩过的一个大坑。</p><div class="danger custom-block"><p class="custom-block-title">用英文原版 DLL 的偏移去读新 DLL，会读出满屏乱码</p><p>原因是新 DLL 是<strong>重新编译</strong>的：<code>#US</code> 字符串堆的<strong>基准偏移和内部布局都变了</strong>。</p></div><p><strong>正确做法</strong>——用「补丁前的自己」当基准：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">raw     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;out/Assembly-CSharp.dll&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;rb&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).read()      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 补丁前（无填充，链式解析可靠）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ents    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.entries(raw, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.find_us(raw)[:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patched </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;patched/Assembly-CSharp.dll&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;rb&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).read()  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 ents 的偏移去读它</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>结果：未变 552 条 / 已译 210 条 / <strong>异常 0</strong> / 长度未变 ✓</p><hr><h2 id="二、两种字符串堆-字节搜索要分清" tabindex="-1">二、两种字符串堆，字节搜索要分清 <a class="header-anchor" href="#二、两种字符串堆-字节搜索要分清" aria-label="Permalink to &quot;二、两种字符串堆，字节搜索要分清&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">一个容易搞混的地方</p><ul><li><code>#US</code> <strong>用户字符串堆</strong>（就是界面上显示的文本）是 <strong>UTF-16</strong> 编码</li><li><code>#Strings</code> <strong>类型名堆</strong>是 <strong>UTF-8</strong> 编码</li></ul><p>用字节搜索时如果搞混，会搜不到或搜出乱码。</p></div><hr><h2 id="三、参数注入的落点-源码实证" tabindex="-1">三、参数注入的落点（源码实证） <a class="header-anchor" href="#三、参数注入的落点-源码实证" aria-label="Permalink to &quot;三、参数注入的落点（源码实证）&quot;">​</a></h2><p>这是「哪个参数改的是哪行代码」的权威对照。改注入点时对着看。</p><h3 id="伤害类-一处分派覆盖四类" tabindex="-1">伤害类：一处分派覆盖四类 <a class="header-anchor" href="#伤害类-一处分派覆盖四类" aria-label="Permalink to &quot;伤害类：一处分派覆盖四类&quot;">​</a></h3><p>在 <code>Compartment.cs</code> 里的伤害计算点，按武器类型分派：</p><table tabindex="0"><thead><tr><th>参数</th><th>落点</th><th>说明</th></tr></thead><tbody><tr><td><code>torpedo.damageMul</code></td><td><code>Compartment.cs</code> 统一伤害基数（<code>weaponType==0</code>）</td><td>鱼雷命中伤害</td></tr><tr><td><code>gun.damageMul</code></td><td>同上（<code>weaponType==1</code>）</td><td>主炮命中伤害</td></tr><tr><td><code>bomb.damageMul</code></td><td>同上（<code>else</code> 分支）</td><td>航弹命中伤害</td></tr><tr><td><code>dc.damageMul</code></td><td>同上（按 <code>Blastzone.isdepthcharge</code> 判定）</td><td>深弹伤害</td></tr><tr><td><code>hedgehog.damageMul</code></td><td><code>Compartment.cs</code> <strong>刺猬独立分支</strong></td><td>唯一不走 Blastzone 的路径</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关键约束：倍率乘在随机之前</p><p>原版伤害基数后面还有 <code>num *= Random.Range(0.8f, 1.2f)</code> 这类随机散布。倍率只放大<strong>基数</strong>，不碰随机范围——否则会破坏原版分布。</p></div><h3 id="探测-经济-航空-ai" tabindex="-1">探测 / 经济 / 航空 / AI <a class="header-anchor" href="#探测-经济-航空-ai" aria-label="Permalink to &quot;探测 / 经济 / 航空 / AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>落点</th></tr></thead><tbody><tr><td><code>sensor.sonarRangeMul</code> × <code>sensor.radarRangeMul</code></td><td><code>ShipData.cs</code> 的 <code>visualRange</code>（<strong>两者乘积</strong>，因为原版只有一个距离源）</td></tr><tr><td><code>economy.renownGainMul</code></td><td><code>DynamicCampaign.cs</code> 威望结算 + <code>UIFunctions.cs</code> 发放点</td></tr><tr><td><code>air.wingSizeMul</code></td><td><code>UIFunctions.cs</code> / <code>CombatAI.cs</code> 的 <code>airStrikesAvailable</code></td></tr><tr><td><code>ai.reactionMul</code></td><td><code>UIFunctions.cs</code> 的 <code>autoNextTimer</code> → <code>AutoNext</code> 协程（延迟 ÷ 倍率）</td></tr><tr><td><code>repair.timeMul</code></td><td><code>DynamicCampaign.GetRepairTime()</code> 返回前（仅玩家方）</td></tr><tr><td><code>torpedo.turnMul</code></td><td><code>Projectile.cs</code> 的 <code>RotateTowards</code> 转向步长</td></tr></tbody></table><h3 id="模型注入" tabindex="-1">模型注入 <a class="header-anchor" href="#模型注入" aria-label="Permalink to &quot;模型注入&quot;">​</a></h3><p><code>LevelLoadManager.cs</code> 共 <strong>12 处</strong> <code>Resources.Load(&quot;ships/&quot;+name)</code> → 已改为 <code>ModModels.LoadShipModel(...)</code>。</p><h3 id="沙盒开关" tabindex="-1">沙盒开关 <a class="header-anchor" href="#沙盒开关" aria-label="Permalink to &quot;沙盒开关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>落点</th></tr></thead><tbody><tr><td><code>unlock.allShips</code></td><td><code>Database.rnClassAvailability[]</code> / <code>kmClassAvailability[]</code> 全部置 0</td></tr><tr><td><code>sandbox.startRenown</code></td><td><code>DynamicCampaign.InitialiseCampaign()</code>（紧接 <code>InitialisePlayerData()</code> 之后）</td></tr><tr><td><code>sandbox.instantRepair</code></td><td><code>DynamicCampaign.GetRepairTime()</code> 返回前</td></tr><tr><td><code>sandbox.timeScale</code></td><td><code>ModPanel.Update()</code> 每帧写 <code>Time.timeScale</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">为什么起始威望必须加在 <code>InitialisePlayerData()</code> 之后</p><p><code>InitialiseCampaign</code> 里 <code>currentRenown</code> 先被设为 10000，随后被 <code>InitialisePlayerData()</code> 覆盖成 380000/280000。种子加在<strong>之前</strong>会被冲掉。</p></div><hr><h2 id="四、一个必须遵守的物理约束-为什么不做「弹速倍率」" tabindex="-1">四、一个必须遵守的物理约束：为什么不做「弹速倍率」 <a class="header-anchor" href="#四、一个必须遵守的物理约束-为什么不做「弹速倍率」" aria-label="Permalink to &quot;四、一个必须遵守的物理约束：为什么不做「弹速倍率」&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">炮弹/鱼雷的初速参与游戏的射击解算</p><p>游戏按<strong>固定弹速预解算弹道</strong>。直接改初速会导致瞄准偏移。</p><p>所以弹速类<strong>不做参数</strong>；只有像「转向灵活度」「修理时长」这种<strong>不参与解算</strong>的量才安全。</p></div><hr><h2 id="五、反编译缺陷修复" tabindex="-1">五、反编译缺陷修复 <a class="header-anchor" href="#五、反编译缺陷修复" aria-label="Permalink to &quot;五、反编译缺陷修复&quot;">​</a></h2><p>反编译工具（ILSpy）有时会产出有缺陷的代码，需要逐行精确修：</p><ul><li>脚本：<code>build/fix_ilspy_defects.py</code></li><li>做法：<strong>按行号精确修</strong> <code>yield break</code>，<strong>不是</strong>全局字符串替换</li></ul><div class="tip custom-block"><p class="custom-block-title">行号会漂移</p><p>以上源码行号随 ILSpy / 游戏版本可能偏移。定位时以「<strong>符号名 + 上下文</strong>」为准，<strong>勿盲信行号</strong>。</p></div><hr><h2 id="六、验证方法论" tabindex="-1">六、验证方法论 <a class="header-anchor" href="#六、验证方法论" aria-label="Permalink to &quot;六、验证方法论&quot;">​</a></h2><p>框架里所有「已完成」的结论，都基于这几类验证：</p><table tabindex="0"><thead><tr><th>验证手段</th><th>能证明什么</th></tr></thead><tbody><tr><td><strong>编译通过</strong></td><td>挂钩绑定成功（方法名写错会报 <code>CS0103</code> / <code>CS0117</code>）</td></tr><tr><td><strong>DLL 字节核验</strong></td><td>类型名、方法名、常量确实在包里（分 UTF-16 / UTF-8 两个堆查）</td></tr><tr><td><strong>汉化无损核验</strong></td><td>补丁后条数不变（正常 213 条）</td></tr><tr><td><strong>分享码往返</strong></td><td>编码→解码内容一致</td></tr><tr><td><strong>一键流水线</strong></td><td>端到端构建产物正常、定版 APK 未被改</td></tr></tbody></table><h3 id="做不到的验证" tabindex="-1">做不到的验证 <a class="header-anchor" href="#做不到的验证" aria-label="Permalink to &quot;做不到的验证&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">真机交互无法在本机验证</p><p>本机<strong>没有安卓模拟器、没有真机</strong>（模拟器因内存 / 安全策略受阻）。</p><p>因此这些只能靠作者真机复测：悬浮窗拖动手感、触屏点击、OnGUI 在高分屏上的字号、剪贴板、存档写盘。</p><p>框架已做<strong>代码级绑定 + 逻辑核验 + 单测</strong>，但不等价于实机通过。</p></div><hr><h2 id="七、其他技术约束速查" tabindex="-1">七、其他技术约束速查 <a class="header-anchor" href="#七、其他技术约束速查" aria-label="Permalink to &quot;七、其他技术约束速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td>语言</td><td><strong>C# 3.0</strong>（Unity 4.7 / .NET 3.5），见 <a href="/AtlanticFleetSite/docs/dev/cs30-limits">兼容约束</a></td></tr><tr><td>AssetBundle</td><td>必须 <code>UncompressedAssetBundle</code>（<code>CreateFromFile</code> 只能读不压缩包）</td></tr><tr><td>分享码</td><td><code>AFMOD1:</code> + Base64（不用 gzip，因 .NET 3.5 压缩库在 Mono 下不确定）</td></tr><tr><td>剪贴板</td><td>Unity 4.7 没有 <code>GUIUtility.systemCopyBuffer</code>，走 Android JNI</td></tr><tr><td>输入</td><td>OnGUI 与 NGUI 是<strong>两套独立管线</strong>，互不拦截</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>源码结构 → <a href="/AtlanticFleetSite/docs/dev/codebase">框架源码结构</a></li><li>改框架 → <a href="/AtlanticFleetSite/docs/dev/hack">如何修改框架本身</a></li><li>名词 → <a href="/AtlanticFleetSite/docs/glossary">术语表</a></li></ul>`,48)])])}const k=a(o,[["render",i]]);export{g as __pageData,k as default};
